#include <bits/stdc++.h>
using namespace std;

// Структура DSU (СНМ) с обеими эвристиками
struct DSU {
    vector<int> parent;
    vector<int> size;

    DSU(int n) {
        parent.resize(n);
        size.resize(n, 1);
        for(int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    // Поиск корня (лидера) со сжатием пути
    int find_set(int v) {
        if (v == parent[v])
            return v;
        // Рекурсивный вызов и переподвешивание
        return parent[v] = find_set(parent[v]);
    }

    // Объединение множеств по размеру
    void union_sets(int a, int b) {
        a = find_set(a);
        b = find_set(b);
        if (a != b) {
            // Подвешиваем меньшее к большему
            if (size[a] < size[b])
                swap(a, b);
            parent[b] = a;
            size[a] += size[b];
        }
    }
};

int main() {
    int n = 5;
    DSU dsu(n + 1);
    dsu.union_sets(1, 2);
    dsu.union_sets(3, 4);

    // Проверка, в одном ли они множестве
    if (dsu.find_set(1) == dsu.find_set(2)) {
        cout << "1 and 2 are connected\n";
    }
    return 0;
}
